import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written pricing double (unit prices in euros); records the skus asked for.
const prices = { apple: 2.5, pear: 10, gold: 150, cheap: 0.99, hundred: 100 }
const asked = []
const pricing = { async priceOf(sku) { asked.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const create = async (items) => {
  const res = await post({ items })
  return { res, body: await res.json() }
}

test('POST /orders creates an order: 201, json, string id, items echoed, total', async () => {
  const { res, body } = await create([{ sku: 'apple', qty: 2 }])
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, [{ sku: 'apple', qty: 2 }])
  assert.equal(body.total, 5)
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
})

test('POST /orders asks pricing for each sku', async () => {
  asked.length = 0
  await create([{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 1 }])
  assert.deepEqual(asked, ['apple', 'pear'])
})

test('POST /orders ids are sequential strings', async () => {
  const a = (await create([{ sku: 'apple', qty: 1 }])).body.id
  const b = (await create([{ sku: 'apple', qty: 1 }])).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('POST /orders total is floored, not rounded', async () => {
  const { body } = await create([{ sku: 'cheap', qty: 3 }]) // 2.97
  assert.equal(body.total, 2)
})

test('POST /orders no discount at exactly 100', async () => {
  const { body } = await create([{ sku: 'hundred', qty: 1 }])
  assert.equal(body.total, 100)
})

test('POST /orders 10% discount above 100, then floored', async () => {
  assert.equal((await create([{ sku: 'gold', qty: 1 }])).body.total, 135)
  assert.equal((await create([{ sku: 'hundred', qty: 1 }, { sku: 'cheap', qty: 1 }])).body.total, 90) // 100.99*0.9=90.891
})

test('POST /orders 400 when items missing, not an array, or empty', async () => {
  for (const payload of [{}, { items: 'x' }, { items: [] }]) {
    const res = await post(payload)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders 400 for invalid JSON and for an empty body', async () => {
  for (const raw of ['{nope', '']) {
    // CHARACTERIZATION: current behaviour may be unintended — an empty body parses as {} and is rejected only because items is missing; the message is the same as for invalid JSON.
    const res = await post(undefined, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders with unknown sku or missing qty yields a null total, still 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total is serialised as null and the order is stored; no validation of sku/qty.
  for (const items of [[{ sku: 'unknown', qty: 1 }], [{ sku: 'apple' }]]) {
    const { res, body } = await create(items)
    assert.equal(res.status, 201)
    assert.equal(body.total, null)
  }
})

test('GET /orders/{id} returns the stored order', async () => {
  const { body: created } = await create([{ sku: 'pear', qty: 2 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/{id} for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200 instead of 404.
  const res = await fetch(`${base}/orders/999999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and wrong methods answer 404 no route', async () => {
  const cases = [
    ['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/extra'],
    ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'],
  ]
  for (const [method, path] of cases) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
